#!/usr/bin/env python
"""Verify the durable Constellation agent feedback log for a work id."""

from __future__ import annotations

import argparse
import json
import re
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))
from agent_work_root import durable_root


class FeedbackVerificationError(Exception):
    """Raised when the durable feedback-log invariant is broken."""


_BARE_NONE_RE = re.compile(r"^[-*]?\s*`?none\.?`?\s*$", re.IGNORECASE)
_SIGNAL_SECTIONS = ("Friction / unclear", "Crew-reported friction", "Improvement signals")


def _entry_block(text: str, work_id: str) -> str | None:
    """Return the feedback entry block for work_id (its ## heading to the next ##)."""
    lines = text.splitlines()
    start = None
    for i, line in enumerate(lines):
        if line.startswith("## ") and work_id in line:
            start = i
            break
    if start is None:
        return None
    end = len(lines)
    for j in range(start + 1, len(lines)):
        if lines[j].startswith("## "):
            end = j
            break
    return "\n".join(lines[start:end])


def _boilerplate_errors(entry: str, work_id: str) -> list[str]:
    """Reject content-free entries: every signal bullet is a bare 'none'."""
    bullets: list[str] = []
    in_section = False
    for line in entry.splitlines():
        stripped = line.strip()
        if stripped.startswith("**") and stripped.rstrip(":*").lstrip("*") in (
            s for s in _SIGNAL_SECTIONS
        ):
            in_section = True
            continue
        if stripped.startswith("**"):
            in_section = False
            continue
        if in_section and stripped.startswith(("-", "*")):
            bullets.append(stripped.lstrip("-* ").strip())
    if not bullets:
        return [
            f"feedback entry for {work_id!r} has no bullets under its signal sections "
            f"({', '.join(_SIGNAL_SECTIONS)})"
        ]
    if all(_BARE_NONE_RE.match(b) for b in bullets):
        return [
            f"feedback entry for {work_id!r} is content-free: every signal bullet is a bare "
            "'none'. A 'none' requires a run-specific reason, e.g. "
            "'none — confirmed after review: <what you checked>'"
        ]
    return []


def _current_run_archive_dirs(agent_work: Path, work_id: str) -> list[Path]:
    archive_root = agent_work / "archive"
    if not archive_root.exists():
        return []
    return [
        path
        for path in archive_root.iterdir()
        if path.is_dir() and (path.name == work_id or path.name.endswith(f"-{work_id}"))
    ]


def _durable_feedback_errors(durable: Path, work_id: str) -> list[str]:
    """The durable-log positive check: the shared main-checkout AGENT_FEEDBACK.md."""
    durable_agent_work = durable / ".agent-work"
    feedback = durable_agent_work / "AGENT_FEEDBACK.md"
    errors: list[str] = []

    if not feedback.is_file():
        errors.append(f"missing durable feedback log: {feedback}")
    else:
        text = feedback.read_text(encoding="utf-8")
        if work_id not in text:
            errors.append(f"durable feedback log does not mention work id {work_id!r}: {feedback}")
        else:
            entry = _entry_block(text, work_id)
            if entry is None:
                errors.append(
                    f"work id {work_id!r} appears in {feedback} but not as a '## ' entry heading"
                )
            else:
                errors.extend(_boilerplate_errors(entry, work_id))

    return errors


def _negative_errors(root: Path, work_id: str, phase: str) -> list[str]:
    """The mode-independent negative checks: nothing durable leaked into the work
    area or the archive package, plus the archive-phase structural checks."""
    agent_work = root / ".agent-work"
    errors: list[str] = []

    work_feedback = agent_work / work_id / "AGENT_FEEDBACK.md"
    if work_feedback.exists():
        errors.append(f"feedback log must stay durable, not inside the work area: {work_feedback}")

    work_lessons = agent_work / work_id / "LESSONS.md"
    if work_lessons.exists():
        errors.append(f"lessons playbook must stay durable, not inside the work area: {work_lessons}")

    archive_dirs = _current_run_archive_dirs(agent_work, work_id)
    archived_feedback = [path for base in archive_dirs for path in base.rglob("AGENT_FEEDBACK.md")]
    for path in archived_feedback:
        errors.append(f"feedback log must not be archived with the run package: {path}")
    archived_lessons = [path for base in archive_dirs for path in base.rglob("LESSONS.md")]
    for path in archived_lessons:
        errors.append(f"lessons playbook must not be archived with the run package: {path}")

    if phase == "archive":
        work_area = agent_work / work_id
        if work_area.exists():
            errors.append(f"work area still exists after archive phase: {work_area}")
        if not archive_dirs:
            errors.append(
                f"no archived run package found for work id {work_id!r} under {agent_work / 'archive'}"
            )

    return errors


def _staged_feedback_errors(root: Path, work_id: str) -> list[str]:
    """The fencing-aware positive check: a worktree-local staged trio + citation.

    A delegated commander who is fenced off the main checkout's durable
    `.agent-work/` may instead stage the trio under
    `<root>/.agent-work/staged-feedback/<work_id>/`. Any missing member of the
    trio (including the FENCE.md citation itself) is an error whose message
    makes clear that learning cannot be silently dropped.
    """
    staged = root / ".agent-work" / "staged-feedback" / work_id
    errors: list[str] = []

    feedback = staged / "AGENT_FEEDBACK.md"
    if not feedback.is_file():
        errors.append(
            f"learning cannot be silently dropped: missing staged feedback entry: {feedback}"
        )
    else:
        text = feedback.read_text(encoding="utf-8")
        if work_id not in text:
            errors.append(f"staged feedback entry does not mention work id {work_id!r}: {feedback}")
        else:
            entry = _entry_block(text, work_id)
            if entry is None:
                errors.append(
                    f"work id {work_id!r} appears in {feedback} but not as a '## ' entry heading"
                )
            else:
                errors.extend(_boilerplate_errors(entry, work_id))

    lessons_delta = staged / "lessons-delta.json"
    if not lessons_delta.is_file():
        errors.append(
            f"learning cannot be silently dropped: missing staged lessons delta: {lessons_delta}"
        )
    else:
        try:
            json.loads(lessons_delta.read_text(encoding="utf-8"))
        except ValueError:
            errors.append(f"staged lessons delta is not valid JSON: {lessons_delta}")

    constellation_feedback = staged / "CONSTELLATION_FEEDBACK.md"
    if not constellation_feedback.is_file():
        errors.append(
            "learning cannot be silently dropped: missing staged constellation feedback export: "
            f"{constellation_feedback}"
        )

    fence = staged / "FENCE.md"
    if not fence.is_file():
        errors.append(
            f"learning cannot be silently dropped: missing fence citation: {fence}"
        )
    elif not fence.read_text(encoding="utf-8").strip():
        errors.append(f"fence citation is empty: {fence}")

    return errors


def verify_agent_feedback(
    root: Path, work_id: str, phase: str, durable: Path | None = None
) -> None:
    # The DURABLE feedback log resolves under `durable` (the shared main-checkout
    # root when run inside a linked worktree); the work-area and archive negative
    # checks stay `root`-local (worktree-local). `durable` defaults to `root`, so
    # an explicit --root wins for BOTH.
    if durable is None:
        durable = root

    neg = _negative_errors(root, work_id, phase)
    durable_errors = _durable_feedback_errors(durable, work_id)
    fence_marker = (root / ".agent-work" / "staged-feedback" / work_id / "FENCE.md").is_file()

    if not durable_errors:
        errors = neg
    elif fence_marker:
        errors = neg + _staged_feedback_errors(root, work_id)
    else:
        errors = neg + durable_errors

    if errors:
        raise FeedbackVerificationError("\n".join(errors))


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("work_id")
    parser.add_argument("--root", default=None, type=Path)
    parser.add_argument("--phase", choices=("feedback", "archive"), required=True)
    args = parser.parse_args(argv)

    # Explicit --root wins for BOTH the durable log and the work-area/archive
    # checks. When omitted, work-area/archive stay cwd-local while the durable log
    # resolves to the shared main-checkout root (durable across worktree removal).
    if args.root is not None:
        local_root, durable = args.root, args.root
    else:
        local_root, durable = Path("."), durable_root()

    try:
        verify_agent_feedback(local_root, args.work_id, args.phase, durable=durable)
    except FeedbackVerificationError as exc:
        print(str(exc), file=sys.stderr)
        return 1

    print(f"agent feedback invariant ok: {args.work_id} ({args.phase})")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

def discover_skills(source_root: Path = SOURCE_ROOT) -> list[Skill]:
    if not source_root.exists():
        raise InstallError(f"source skill root does not exist: {source_root}")

    skills: list[Skill] = []
    for source_path in sorted(
        path
        for path in source_root.iterdir()
        if path.is_dir() and not path.name.startswith("_")  # _shared holds bundled refs, not a skill
    ):
        skill_md = source_path / "SKILL.md"
        if not skill_md.exists():
            raise InstallError(f"source skill is missing SKILL.md: {source_path}")
        metadata = parse_frontmatter(skill_md)
        skills.append(
            Skill(
                source_name=source_path.name,
                install_name=metadata["name"],
                source_path=source_path,
                required_scripts=expand_script_bundle(
                    SKILL_SCRIPT_BUNDLES.get(source_path.name, ())),
                required_references=SKILL_REFERENCE_BUNDLES.get(source_path.name, ()),
            )
        )

    if not skills:
        raise InstallError(f"no skills found in {source_root}")
    return skills


def select_skills(requested: Sequence[str] | None, available: Iterable[Skill]) -> list[Skill]:
    skills = list(available)
    if requested is None:
        return skills

    index: dict[str, Skill] = {}
    for skill in skills:
        index[skill.source_name] = skill
        index[skill.install_name] = skill

    selected: list[Skill] = []
    seen: set[str] = set()
    unknown: list[str] = []
    for name in requested:
        skill = index.get(name)
        if skill is None:
            unknown.append(name)
            continue
        if skill.install_name not in seen:
            selected.append(skill)
            seen.add(skill.install_name)

    if unknown:
        valid = ", ".join(sorted(index))
        raise InstallError(f"unknown skill(s): {', '.join(unknown)}. Valid names: {valid}")
    return selected


def validate_required_scripts(skills: Iterable[Skill], scripts_root: Path = REPO_ROOT / "scripts") -> None:
    missing: list[str] = []
    for skill in skills:
        for script in skill.required_scripts:
            if not (scripts_root / script).is_file():
                missing.append(f"{skill.install_name}: {scripts_root / script}")
    if missing:
        raise InstallError(f"required script(s) missing: {'; '.join(missing)}")


